        window.addEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)

import { useSyncExternalStore } from 'react'
import { projectSessionService, type ProjectSessionService } from '../../services/project/project_session_service'

export function useProjectSession(service: ProjectSessionService = projectSessionService) {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => service.getSnapshot(),
        () => service.getSnapshot(),
    )
}

import { Button, Menu, MenuItem } from '@mui/material'
import type { MouseEvent } from 'react'
import { useCallback, useState } from 'react'
import { projectSessionService, type ProjectFolderValues } from '../../services/project/project_session_service'
